package com.zakpruitt.sanitycapped;

import com.zakpruitt.sanitycapped.naming.Naming;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Expected values generated by running the functions in tools/naming.py.
 */
class NamingTest {

    @ParameterizedTest
    @CsvSource({
            "cloudzUlt-128, scCloudzUlt",
            "FUCK-128, scFuck",
            "VynChatting-128, scVynChatting",
            "catJAM_2x, scCatJAM",
            "peepoHmm-128, scPeepoHmm",
            "pepe-laugh, scPepelaugh",
            "OOOO-128, scOooo",
            "scAlready, scAlready",
            "imIn, scImIn",
            "theChosen, scTheChosen",
            "weAreGathered, scWeAreGathered",
            "sadge_512, scSadge",
            "a, scA",
            "MiXeD, scMiXeD",
            "he''llo, scHello",
            "what?now, scWhatnow",
            "dot.dot, scDotdot",
            "big-3x, scBig",
            "x_1234px, scX",
            "scoop, scScoop",
    })
    void matchesTheBuildScript(String stem, String expected) {
        assertThat(Naming.triggerWord(stem)).isEqualTo(expected);
    }

    @ParameterizedTest
    @CsvSource({"'  '", "'---'", "'?!.'", "''"})
    void namesMadeOnlyOfBreakCharactersLeaveNothing(String stem) {
        assertThat(Naming.triggerWord(stem)).isEmpty();
    }

    @ParameterizedTest
    @CsvSource({
            "vine boom!, scVineboom, /scvineboom",
            "BRUH, scBruh, /scbruh",
            "scAlready, scAlready, /scalready",
            "air_horn (loud), scAirhornloud, /scairhornloud",
            "wilhelm-128, scWilhelm, /scwilhelm",
            "MiXeD, scMiXeD, /scmixed",
            "a, scA, /sca",
            "über, scBer, /scber",
    })
    void soundNamesKeepOnlyWhatASlashCommandCanHold(String stem, String name, String command) {
        assertThat(Naming.soundName(stem)).isEqualTo(name);
        assertThat(Naming.command(Naming.soundName(stem))).isEqualTo(command);
    }

    @ParameterizedTest
    @CsvSource({"'  '", "'___'", "'(!)'", "''"})
    void soundNamesWithNoLettersOrDigitsLeaveNothing(String stem) {
        assertThat(Naming.soundName(stem)).isEmpty();
    }
}
